// Actual Torch vmap(func.jvp(aten._prelu_kernel_backward)) references.
use super::*;

#[derive(Clone, Copy)]
struct Golden { values: &'static [f64], shape: &'static [usize], stride: &'static [usize], f64: bool, live: bool, zero: bool }
struct Case { layout: usize, mask: usize, seed64: bool, enabled: bool, outputs: [Option<Golden>;2], gradients: [[Option<Golden>;6];2] }

fn tensor(values: &[f64], shape: &[usize], dtype: DType) -> Tensor {
    Tensor::from_vec_f64(values.to_vec(),shape).unwrap().to_dtype(dtype)
}
fn setup(layout: usize, seed64: bool) -> (Vec<Tensor>, Vec<Tensor>) {
    let shape: &[usize] = match layout {0=>&[],1=>&[4],2=>&[3,2,2],3=>&[3,0,2],4=>&[7],_=>unreachable!()};
    let count=shape.iter().product();
    let x=match layout {
        0=>tensor(&[-2.],shape,DType::F32),
        1=>tensor(&[-2.,-0.,0.,2.],shape,DType::F32),
        2=>tensor(&[-2.,0.,1.,-3.,2.,-1.,4.,-5.,0.,2.,-2.,1.],&[2,2,3],DType::F32).transpose(0,2).unwrap(),
        3=>Tensor::zeros(&[2,0,3]).transpose(0,2).unwrap(),
        4=>tensor(&[f64::NEG_INFINITY,-2.,-0.,0.,2.,f64::INFINITY,f64::NAN],shape,DType::F32),
        _=>unreachable!(),
    };
    let inputs=vec![tensor(&vec![0.7;count],shape,DType::F32),x,tensor(&vec![if layout==4{f64::INFINITY}else{0.3};count],shape,DType::F32)].into_iter().map(|x|x.requires_grad_(true).unwrap()).collect();
    let dtype=if seed64 {DType::F64}else{DType::F32};
    let mut physical=vec![2];physical.extend_from_slice(shape);
    let directions=(0..3).map(|index| {
        let value=0.2+0.1*index as f64;
        let result=if index==1 && (layout==2||layout==3) {
            let base=if layout==2 {vec![2,2,2,3]}else{vec![2,2,0,3]};
            tensor(&vec![value;2*count],&base,dtype).transpose(1,3).unwrap()
        }else{tensor(&vec![value;2*count],&physical,dtype)};
        result.requires_grad_(true).unwrap()
    }).collect();
    (inputs,directions)
}
fn check(actual: &Tensor, expected: &Golden, context: &str) {
    assert_eq!(actual.shape(),expected.shape,"{context}: shape");
    assert_eq!(actual.strides(),expected.stride,"{context}: strides");
    assert_eq!(actual.dtype(),if expected.f64{DType::F64}else{DType::F32},"{context}: dtype");
    assert_eq!(actual.requires_grad(),expected.live,"{context}: requires_grad");
    assert_eq!(actual.is_structural_zero(),expected.zero,"{context}: structural zero");
    assert_eq!(actual.numel(),expected.values.len());
    if expected.zero {assert!(expected.values.iter().all(|v|*v==0.));return;}
    for (index,(a,b)) in actual.to_vec_f64().into_iter().zip(expected.values).enumerate() {
        assert!(a.is_nan()&&b.is_nan() || a==*b || a.is_finite()&&b.is_finite()&&(a-b).abs()<=3e-6*(1.+b.abs()),"{context} value{index}: {a} != {b}");
        if a==0. && *b==0. {assert_eq!(a.is_sign_negative(),b.is_sign_negative(),"{context} zero sign {index}");}
    }
}

#[test]
fn physical_pair_matches_140_actual_torch_values_layouts_flags_and_all_input_adjoints() {
    let mut failures=Vec::new();
    for (index,case) in CASES.iter().enumerate() {
        let result=std::panic::catch_unwind(|| {
            let (inputs,directions)=setup(case.layout,case.seed64);
            let tangents=directions.iter().enumerate().map(|(i,v)|if case.mask&(1<<i)!=0 {Some(v.clone())}else{None}).collect::<Vec<_>>();
            let outputs=crate::autograd::with_grad_enabled(case.enabled,||jvp_physical(&inputs,&tangents,2)).unwrap();
            let references=inputs.iter().chain(&directions).collect::<Vec<_>>();
            for slot in 0..2 {
                let context=format!("case{index} layout{} mask{} seed64{} enabled{} output{slot}",case.layout,case.mask,case.seed64,case.enabled);
                assert_eq!(outputs[slot].is_some(),case.outputs[slot].is_some(),"{context}: presence");
                if let (Some(actual),Some(expected))=(&outputs[slot],case.outputs[slot]) {
                    check(actual,&expected,&context);
                    if actual.requires_grad() {
                        let sum=actual.sum();let one=if sum.dtype()==DType::F64 {Tensor::from_vec_f64(vec![1.],&[]).unwrap()}else{Tensor::scalar(1.)};
                        let gradients=Tensor::vjp_many_wrt_optional(&[&sum],&references,&[&one],false).unwrap();
                        for (input,(actual,expected)) in gradients.iter().zip(&case.gradients[slot]).enumerate() {
                            let context=format!("{context} gradient{input}");
                            assert_eq!(actual.is_some(),expected.is_some(),"{context}: presence");
                            if let (Some(actual),Some(expected))=(actual,expected) {check(actual,expected,&context);}
                        }
                    }
                }
            }
        });
        if result.is_err(){failures.push(index);}
    }
    assert!(failures.is_empty(),"failed actual Torch configurations: {failures:?}");
}

#[test]
fn physical_pair_missing_empty_and_invalid_shapes_are_bounded() {
    let empty=Tensor::zeros(&[1usize<<45,0]);let inputs=vec![empty.clone(),empty.clone(),empty];
    assert!(jvp_physical(&inputs,&[None,None,None],2).unwrap().iter().all(Option::is_none));
    let direction=Tensor::zeros(&[2,1usize<<45,0]);
    let outputs=jvp_physical(&inputs,&[None,Some(direction),None],2).unwrap();
    assert!(outputs[0].is_none());let second=outputs[1].as_ref().unwrap();assert_eq!(second.shape(),[2,1usize<<45,0]);assert_eq!(second.numel(),0);
    let (inputs,dirs)=setup(1,false);
    assert!(jvp_physical(&inputs,&[Some(dirs[0].clone()),None],2).is_err());
    assert!(jvp_physical(&inputs,&[Some(Tensor::ones(&[1,4])),None,None],2).is_err());
    assert!(jvp_physical(&inputs,&[Some(Tensor::from_vec_i64(vec![1;8],&[2,4]).unwrap()),None,None],2).is_err());
    assert!(jvp_physical(&inputs,&[None,None,None],usize::MAX).is_err());
    assert!(inputs.iter().chain(&dirs).all(|v|v.grad().is_none()));
}

